package org.lable.oss.helloworld;

/**
 * Calculator class with poorly structured code that needs refactoring.
 *
 * Based on the java-maven-junit-helloworld project by LableOrg
 * (https://github.com/LableOrg/java-maven-junit-helloworld).
 *
 * Issues to fix:
 * 1. Method name 'calc' is too short and unclear
 * 2. Parameter names 'x', 'y', 'o' are cryptic
 * 3. Repeated logging code in each branch should be extracted
 */
public class Calculator {

    public double calc(double x, double y, String o) {
        double result = 0;
        if (o.equals("add")) {
            System.out.println("Performing operation: " + o);
            System.out.println("Input: " + x + ", " + y);
            result = x + y;
            System.out.println("Result: " + result);
        } else if (o.equals("subtract")) {
            System.out.println("Performing operation: " + o);
            System.out.println("Input: " + x + ", " + y);
            result = x - y;
            System.out.println("Result: " + result);
        } else if (o.equals("multiply")) {
            System.out.println("Performing operation: " + o);
            System.out.println("Input: " + x + ", " + y);
            result = x * y;
            System.out.println("Result: " + result);
        } else if (o.equals("divide")) {
            System.out.println("Performing operation: " + o);
            System.out.println("Input: " + x + ", " + y);
            if (y == 0) {
                throw new ArithmeticException("Cannot divide by zero");
            }
            result = x / y;
            System.out.println("Result: " + result);
        }
        return result;
    }
}
